const main = items[0].json;

const output = {
  time:    main.meta.triggered_at,
  crop:    main.crop ?? null,
  sensors: (main.sensors ?? []).map(s => ({
    type:  s.type,
    value: s.value
  })),
  weather: {
    state:                     main.weather.state,
    precipitation_probability: main.weather.precipitation_probability,
    summary:                   main.weather.summary
  },
  image_processing: {
    features:   main.image_processing.features ?? null,
    confidence: main.image_processing.confidence ?? null
  },
  warnings: (main.warnings ?? []).map(w => ({
    name: w.name
  }))
};

return [{ json: output }];

