parameters.jsCode:
const raw      = JSON.parse($input.first().json.output);
const mainJson = { ...$('Sensors_Updater').first().json };

// ─── Merge warnings ───────────────────────────────────────────────────────────
const warningsMap = {};
raw.forEach(w => {
  warningsMap[w.name.toLowerCase()] = w;
});
mainJson.warnings = mainJson.warnings.map(w => {
  const updated = warningsMap[w.name.toLowerCase()];
  if (!updated) return w;
  return {
    ...w,
    active:      updated.active,
    severity:    updated.severity,
    description: updated.description
  };
});

// ─── Recommended action for semi-auto actuators ───────────────────────────────
mainJson.actuators = mainJson.actuators.map(a => {
  if (a.control_mode !== 'semi-auto') return a;
  let recommended_action = null;
  switch (a.classification) {
    case 'TURN-ON':
      recommended_action = `Turn on the ${a.type} for ${a.run.duration_minutes ?? '?'} minutes starting from ${a.run.execute_at ?? '?'}.`;
      break;
    case 'TURN-OFF':
      recommended_action = `Turn off the ${a.type} immediately, conditions no longer require it.`;
      break;
    case 'KEEP-ON':
      recommended_action = `Keep the ${a.type} running, current conditions still require it.`;
      break;
    case 'KEEP-OFF':
      recommended_action = `Keep the ${a.type} off, no action is needed at this time.`;
      break;
    case 'FUTURE-RE-EVALUATING':
    case 'NEED-RE-EVALUATION':
      recommended_action = null;
      break;
    default:
      recommended_action = null;
  }
  return { ...a, recommended_action };
});

// ─── Remove history ───────────────────────────────────────────────────────────
delete mainJson.history;

return [{ json: mainJson }];
